import base64, json, os, sys, time, urllib.error, urllib.request
from datetime import datetime, timezone, timedelta

API = "https://api.github.com"
PERMISSIONS = {"actions": "write", "metadata": "read"}   # a subset of platform/github-app/lanes.json platform-engineer


def b64(b):
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode()


def app_jwt(app_id, pem):
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.asymmetric import padding
    now = int(time.time())
    head = b64(json.dumps({"alg": "RS256", "typ": "JWT"}).encode())
    body = b64(json.dumps({"iat": now - 60, "exp": now + 540, "iss": app_id}).encode())
    key = serialization.load_pem_private_key(pem, password=None)
    sig = key.sign(f"{head}.{body}".encode(), padding.PKCS1v15(), hashes.SHA256())
    return f"{head}.{body}.{b64(sig)}"


def call(method, path, token, body=None):
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(API + path, method=method, data=data, headers={
        "Authorization": f"Bearer {token}", "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "estate-drill-dispatcher"})
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            raw = r.read()
            return r.status, (json.loads(raw) if raw else None)
    except urllib.error.HTTPError as e:
        return e.code, e.read()[:200].decode(errors="replace")


def by_the_clock(r):
    """True if this run is the hourly heartbeat itself: GitHub's cron, or this Job.
    A push, a pull_request or a hand dispatch is somebody working, and stops the
    moment they do -- which is exactly the hour a heartbeat has to cover."""
    ev = r.get("event")
    if ev == "schedule":
        return True
    actor = str(((r.get("triggering_actor") or {}).get("login")) or "")
    return ev == "workflow_dispatch" and actor.endswith("[bot]")


def period_hours(cron):
    """Hours between two firings of a catalogue cron. Only the shapes drills/catalogue.yaml
    uses: `m * * * *` hourly, `m */N * * *` every N hours, `m H1,H2,.. * * *` an evenly
    spaced hour list (crew#684: catalog-render's `58 1,7,13,19`), `m H * * *` daily,
    `m H * * D` weekly. Anything else is refused loudly, never guessed."""
    return _period_and_offset(cron)[0]


def _period_and_offset(cron):
    """(hours between firings, the hour the first firing of the day is at)."""
    minute, hour, dom, mon, dow = cron.split()
    if dom != "*" or mon != "*":
        raise ValueError("unsupported cron %r" % cron)
    if minute.startswith("*/") and minute[2:].isdigit() and int(minute[2:]) % 15 == 0 and 60 % int(minute[2:]) == 0 and hour == "*":
        return int(minute[2:]) / 60, 0          # crew#648: an N-minute period, as a fraction of an hour
    if not minute.isdigit():
        raise ValueError("unsupported cron %r" % cron)
    if hour == "*":
        return 1, 0
    if hour.startswith("*/") and hour[2:].isdigit() and 24 % int(hour[2:]) == 0:
        return int(hour[2:]), 0
    if "," in hour and all(h.isdigit() for h in hour.split(",")):
        hours = [int(h) for h in hour.split(",")]
        steps = {b - a for a, b in zip(hours, hours[1:])}
        if len(steps) == 1 and 24 % len(hours) == 0 and steps == {24 // len(hours)}:
            return 24 // len(hours), hours[0]
        raise ValueError("unsupported cron %r (hours are not evenly spaced)" % cron)
    if hour.isdigit():
        return (168 if dow != "*" else 24), 0
    raise ValueError("unsupported cron %r" % cron)


def bucket_and_due(cron, now):
    """(start of the period `now` is in, the moment the cron fires inside it). Hourly keeps
    the original rule -- due at the top of the hour, so the Job at :03 covers the hour
    before GitHub's cron gets its chance. Slower crons are due at their own H:M, so a
    daily 07:41 drill is not dispatched at 00:03 and again by the cron at 07:41."""
    minute, hour, _dom, _mon, dow = cron.split()
    p, offset = _period_and_offset(cron)
    day = now.replace(hour=0, minute=0, second=0, microsecond=0)
    if p < 1:
        n = int(round(p * 60))
        start = now.replace(minute=(now.minute // n) * n, second=0, microsecond=0)
        return start, start
    if p == 1:
        start = now.replace(minute=0, second=0, microsecond=0)
        return start, start
    if p < 24:
        # an hour list `1,7,13,19` fires at offset 1: the period holding 00:03 began
        # at 19:00 the day before and its firing was 19:58 (floor division carries)
        start = day + timedelta(hours=((now.hour - offset) // p) * p + offset)
        return start, start + timedelta(minutes=int(minute))
    if p == 24:
        return day, day + timedelta(hours=int(hour), minutes=int(minute))
    start = day - timedelta(days=now.weekday())            # Monday 00:00; cron dow 1 = Monday
    return start, start + timedelta(days=(int(dow) - 1) % 7, hours=int(hour), minutes=int(minute))


def plan(runs, now, cron="0 * * * *"):
    """'dispatch' unless the CLOCK already ran this workflow in the current period, or the
    period's own firing time has not come yet (crew#554 CP4, 2026-08-29: verify-drill
    33234050516 graded `estate-escrow.yml fired 0 of 4 promised in 24h` and
    `kyverno-secrets-drill last green 34.0h ago` -- GitHub dropped both schedules and this
    Job only knew hours).

    Measured 2026-08-28 11:5xZ over 24h, the reason this is not "any run": of the
    24 hours, login-drill had a run in 19 but only 3 were clock-driven, 16 being
    push-only; trace-drill 13 push-only, verify-drill 11. Suppressing on a push
    handed those hours back to whoever happened to be pushing, and bin/idp-drills-row
    counts only schedule + App runs, so the row read them as dropped and could never
    go green on a repo anyone works in. The two now use one definition of the clock
    and tests/test_incident_crew554_drills_run_on_the_estates_clock.py holds them to it."""
    start, due = bucket_and_due(cron, now)
    for r in runs:
        at = datetime.strptime(r["created_at"], "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
        if at >= start and by_the_clock(r):
            return "skipped: %s run %s started %s" % (r.get("event"), r.get("id"), r["created_at"])
    if now < due:
        return "skipped: not due until %s" % due.strftime("%Y-%m-%dT%H:%M:%SZ")
    return "dispatch"


def main():
    repo = os.environ["GITHUB_REPO"]
    # `<workflow>=<cron, spaces as _>`: the catalogue's own schedule decides the period
    workflows = [w.split("=", 1) for w in os.environ["WORKFLOWS"].split()]
    d = os.environ["GITHUB_APP_DIR"]
    app_id = open(os.path.join(d, "githubAppID")).read().strip()
    inst = open(os.path.join(d, "githubAppInstallationID")).read().strip()
    pem = open(os.path.join(d, "githubAppPrivateKey"), "rb").read()
    at = datetime.now(timezone.utc)
    stamp = at.strftime("%Y-%m-%dT%H:%M:%SZ")
    code, tok = call("POST", f"/app/installations/{inst}/access_tokens", app_jwt(app_id, pem), {"permissions": PERMISSIONS})
    if code != 201:
        print(f"FAIL drill-dispatcher installation token -> {code} {tok!s:.120} at {stamp}"); sys.exit(1)
    token = tok["token"]
    code, meta = call("GET", f"/repos/{repo}", token)
    if code != 200:
        print(f"FAIL drill-dispatcher GET /repos/{repo} -> {code} at {stamp}"); sys.exit(1)
    ref, failed = meta["default_branch"], 0
    for wf, cron in workflows:
        # 30, not 5: with pushes no longer suppressing, the clock run still has to be FOUND,
        # and login-drill alone took 24 push runs in 24h (crew#554).
        code, page = call("GET", f"/repos/{repo}/actions/workflows/{wf}/runs?per_page=30", token)
        runs = page.get("workflow_runs", []) if code == 200 and isinstance(page, dict) else []
        verdict = plan(runs, at, cron.replace("_", " "))
        if verdict != "dispatch":
            print(f"ok   drill-dispatcher {wf} {verdict} at {stamp}"); continue
        code, err = call("POST", f"/repos/{repo}/actions/workflows/{wf}/dispatches", token, {"ref": ref})
        if code == 204:
            print(f"ok   drill-dispatcher {wf} dispatched on {ref} at {stamp}")
        else:
            failed += 1; print(f"FAIL drill-dispatcher {wf} dispatch -> {code} {err!s:.120} at {stamp}")
    sys.exit(1 if failed else 0)


if __name__ == "__main__":
    main()
