import datetime, json, time, urllib.parse, urllib.request
AM = "http://kps-alertmanager.monitoring.svc:9093"
PROM = "http://kps-prometheus.monitoring.svc:9090"
def get(url):
    with urllib.request.urlopen(url, timeout=10) as r:
        return json.load(r)
def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
start, line, err = time.time(), None, ""
while time.time() - start < 480:
    try:
        alerts = [a for a in get(AM + "/api/v2/alerts?active=true&filter=" + urllib.parse.quote('alertname="FounderSurfaceDown"'))
                  if "langfuse" in a["labels"].get("instance", "")]
        q = get(PROM + "/api/v1/query?query=" + urllib.parse.quote('sum(increase(alertmanager_notifications_total{integration="telegram"}[15m]))'))["data"]["result"]
        sent = float(q[0]["value"][1]) if q else 0.0
        if alerts and sent > 0:
            line = f"ok langfuse-alert-drill FounderSurfaceDown firing for {alerts[0]['labels']['instance']} telegram_notifications={sent:.0f} after {int(time.time() - start)}s at {now()}"
            break
    except Exception as e:
        err = str(e)[:80]
    time.sleep(30)
if line is None:
    line = f"FAIL langfuse-alert-drill no FounderSurfaceDown for langfuse with a telegram notification within 480s at {now()} {err}"
open("/tmp/receipt", "w").write(line + "\n")
print(line)
